// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy and init
        c.init(address(0x1), address(0x2), address(0x3));

        // Create a grant proposal (proposalID = 1) to satisfy cancelProposal requirements
        address recipient = address(0x4);
        uint amount = 100;
        vm.prank(address(0x5));
        c.newGrantProposal(recipient, amount);

        // Create an address proposal (proposalID = 2) with type = "GRANT" so isEqual passes
        address proposedAddress = address(0x6);
        vm.prank(address(0x7));
        c.newAddressProposal(proposedAddress, "GRANT");

        // Ensure proposal 1 is finalising (required for cancelProposal)
        // We need mapPID_finalising[1] == true. Call finaliseProposal? No, we directly call the internal _finalise by satisfying conditions in voteProposal.
        // Simpler: use vm.prank to call cancelProposal. But first, we must make proposal 1 finalising.
        // We can call cancelProposal on proposal 1 with proposal 2 as newProposalID, but we need mapPID_finalising[1]==true.
        // Let's make proposal 1 finalising via a vote that triggers majority (but we don't have VAULT weight).
        // Alternative: directly set via mapping? Not allowed. We'll create a scenario where proposal 1 is finalising by having hasQuorum and hasMajority pass.
        // Since VAULT is not set up, totalWeight() will return 0. So votes > 0 is true for quorum and majority. So a single vote will trigger _finalise.
        vm.prank(address(0x5));
        c.voteProposal(1); // This should finalise proposal 1

        // Now proposal 1 is finalising. cancelProposal(1,2) requires:
        // 1) mapPID_finalising[1] == true -> satisfied
        // 2) newProposalID != oldProposalID -> 2 != 1 -> satisfied
        // 3) hasMinority(2) -> votes[2] must be > totalWeight/6. totalWeight is 0 (VAULT not set), so votes[2] > 0 is true. votes[2] is 0 by default? No, we never voted on 2. So 0 > 0 false. We need to vote on proposal 2 to increase its votes.
        vm.prank(address(0x7));
        c.voteProposal(2); // Now votes[2] > 0

        // 4) isEqual(type[1], type[2]) -> type[1] = "GRANT", type[2] = "GRANT" -> true

        // Now call cancelProposal
        vm.prank(address(0x5));
        c.cancelProposal(1, 2);

        // Check proposalCount
        // In reference P: proposalCount == 2 (one from newGrantProposal, one from newAddressProposal with single increment)
        // In buggy M: proposalCount == 3 (one from newGrantProposal, two from newAddressProposal)
        assertTrue(c.proposalCount() == 2, "proposalCount should be 2 in reference");
    }
}

