pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up VADER, USDV, VAULT mock addresses (any non-zero address works)
        c.init(address(1), address(2), address(3));

        // Create two GRANT proposals; first gets ID 1, second gets ID 2
        c.newGrantProposal(address(0x10), 100);
        c.newGrantProposal(address(0x20), 200);

        // Need to make proposal 1 finalising so cancelProposal can be called
        // We simulate a vote to trigger _finalise via hasQuorum + hasMajority
        // But totalWeight is 0, so hasQuorum fails. Instead, directly call voteProposal
        // which will set mapPID_votes[1] = 0 and not finalise. 
        // Actually easier: we can call _finalise through voteProposal by having weight.
        // Since VAULT returns 0 for getMemberWeight and totalWeight, we use vm.warp to bypass time? No.
        // Let's directly trigger finalising by voting. 
        // With VAULT.totalWeight() = 0, quorum is 0/3 = 0, votes=0, so votes > 0 is false.
        // So we need to set VAULT weight. Since VAULT is mock, we cannot. 
        // Instead, we can call finaliseProposal which requires mapPID_finalising true.
        // Let's use vm.store to set mapPID_finalising[1] = true? Not allowed.
        // Alternative: call cancelProposal requires oldProposal finalising. 
        // We can craft a different approach: call voteProposal which may set finalising if quorum true.
        // But without VAULT control, we can't. 
        // Instead, note bug: after cancelProposal, proposalCount differs. 
        // cancelProposal only counts proposals, not creates them. So we just need any two proposals existing.
        // The bug is in newGrantProposal incrementing twice, so after creating proposals count differs
        // regardless of cancelProposal. 
        // So simpler: just create one newGrantProposal and check proposalCount directly.
        // reference: 1 increment → 1 proposal. buggy: 2 increments → 2 proposals?
        // Actually proposalCount starts at 0, after first newGrantProposal: reference=1, buggy=2.
        // So we can assert proposalCount == 1 (reference) vs !=1 (buggy).
        // Let's do that.
        c.newGrantProposal(address(0x10), 100);
        assertTrue(c.proposalCount() == 1, "proposalCount should be 1");
    }
}

