pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy mock contracts for VADER, USDV, VAULT
        // We need a minimal mock that the test can interact with
        // Since we cannot import external contracts, we use a simple approach:
        // Deploy dummy addresses that satisfy external calls
        address mockVader = address(0x1);
        address mockUsdv = address(0x2);
        address mockVault = address(0x3);

        // Initialize the contract
        c.init(mockVader, mockUsdv, mockVault);

        // Create a grant proposal (proposal ID 1) to have finalising state
        vm.prank(address(0x100));
        c.newGrantProposal(address(0x200), 100);

        // Vote on proposal 1 to set a valid vote weight
        // Need a vault that returns non-zero totalWeight and getMemberWeight
        // Use vm.store to set state directly? NO - only public surface
        // Instead, we can't easily set vault's totalWeight without a real contract.
        // For concrete test to work, we need to mock VAULT behavior.
        // The simplest way: deploy a mock vault contract.
        // But the rules say only C.sol is imported. So we must deploy a mock.
        // Let's use a simple approach: deploy a dummy vault that returns 10 for totalWeight
        // and 6 for getMemberWeight of msg.sender

        // To satisfy the requirement, we create a minimal vault-like contract inline
        // (But that would be another contract - not allowed)
        // So we must rely on the default vault being address(0) and accept that
        // totalWeight() returns 0. That makes hasQuorum/hasMajority fail.
        // The test must still work.
        // 
        // Alternative: use the fact that without a real VAULT, totalWeight() returns 0
        // Then hasQuorum(proposalID) returns false (0 > 0 false)
        // hasMajority(proposalID) returns false
        // hasMinority(proposalID) returns false
        // 
        // To trigger cancelProposal, we need hasMinority(newProposalID) = true
        // which requires mapPID_votes[newProposalID] > totalWeight()/6 = 0
        // So we need at least 1 vote on newProposalID
        // 
        // The difference in VADER after cancelProposal: 
        // cancelProposal does not change VADER directly, so P and M would have same VADER
        // unless moveUtils or other internal function is called.
        // 
        // Actually, the difference is that cancelProposal emits CancelProposal which reads VADER
        // via iVADER(VADER) in the event? No, event just passes VADER address.
        // The getter VADER() will return different values in P vs M after init.
        // 
        // So the assertion can be: after init, c.VADER() != address(0) for reference, == address(0) for bug.
        // That's direct and simple.

        // Start fresh
        c = new C();
        vm.prank(address(0x100));
        c.init(mockVader, mockUsdv, mockVault);

        // Assert that VADER is set (non-zero) 
        assertTrue(c.VADER() != address(0), "VADER should be set after init");
    }
}

