pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy three mock addresses for VADER, USDV, VAULT
        address vader = address(0x1111111111111111111111111111111111111111);
        address usdv = address(0x2222222222222222222222222222222222222222);
        address vault = address(0x3333333333333333333333333333333333333333);

        // Initialize with the three addresses
        c.init(vader, usdv, vault);

        // Create a grant proposal
        address recipient = address(0x4444444444444444444444444444444444444444);
        c.newGrantProposal(recipient, 100);

        // Vote on the proposal to make it finalising
        c.voteProposal(1);

        // Now create a second proposal of the same type (GRANT) so that cancelProposal can be called
        c.newGrantProposal(recipient, 200);

        // Vote on the second proposal to make it have minority
        c.voteProposal(2);

        // Now call cancelProposal(oldProposalID=1, newProposalID=2)
        // This should execute successfully in the reference
        // In the buggy version, the call to iVAULT(VAULT).totalWeight() will revert because VAULT is set to usdv which is not a VAULT contract
        try c.cancelProposal(1, 2) {
            // If no revert, check that the VAULT address is correctly set to vault (original) not usdv (buggy)
            assertTrue(c.VAULT() == vault, "VAULT should be the vault address");
        } catch {
            // In the buggy version, the call reverts because VAULT points to usdv
            // So we assert that the VAULT address is incorrectly set to usdv
            assertTrue(c.VAULT() == usdv, "Bug: VAULT should be usdv after revert");
        }
    }
}

