        // Init contract—reference sets VAULT = mockVault, bug sets VAULT = mockUSDV
        c.init(mockVader, mockUSDV, mockVault);

        // Create a GRANT proposal (any type works)
        c.newGrantProposal(address(0x1234), 1 ether);
        uint proposalID = 1;

        // Fast-forward past coolOffPeriod
        vm.warp(block.timestamp + 2 days);

        // Call finaliseProposal—this invokes grantFunds which checks
        // iERC20(USDV).balanceOf(VAULT). In reference: VAULT = mockVault, so reads mockVault's USDV balance.
        // In bug: VAULT = mockUSDV, so reads mockUSDV's own USDV balance (which is 0).
        // To make reference pass, we set mockUSDV balance on mockVault = enough.
        // The assertion: after finalise, the reference sets mapPID_finalised[1] = true, bug reverts.
        bool ok;
        try c.finaliseProposal(proposalID) { ok = true; } catch { ok = false; }
        assertTrue(ok, "finaliseProposal should succeed on reference");
    }
}

