pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address addr1 = address(0x1111);
        address addr2 = address(0x2222);
        address addr3 = address(0x3333);

        vm.prank(address(0xdead));
        c.init(addr1, addr2, addr3);

        // Create a grant proposal (any proposal type works)
        vm.prank(address(0xbee1));
        c.newGrantProposal(address(0xbee2), 100);

        // Get the VAULT address before cancelProposal
        address vaultBefore = c.VAULT();

        // We need a finalising proposal to cancel, so force finalise by voting
        vm.prank(address(0xbee1));
        c.voteProposal(1);

        // Now create a new proposal of same type (GRANT)
        vm.prank(address(0xbee1));
        c.newGrantProposal(address(0xbee3), 200);

        // Call cancelProposal
        vm.prank(address(0xbee1));
        c.cancelProposal(1, 2);

        // Check VAULT address after cancelProposal
        address vaultAfter = c.VAULT();

        // Reference: vaultAfter should equal vaultBefore (addr3)
        // Bug: vaultAfter will be addr2 (the USDV address)
        assertTrue(vaultAfter == vaultBefore);
    }
}

