pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up distinct addresses for VADER, USDV, VAULT
        address addrVADER = address(0x1);
        address addrUSDV = address(0x2);
        address addrVAULT = address(0x3);

        // Init contract
        c.init(addrVADER, addrUSDV, addrVAULT);

        // Create a grant proposal to set mapPID_finalising[1] = true
        c.newGrantProposal(address(0x4), 1);

        // Vote to trigger finalising (requires > 1/3 totalWeight, but VAULT is mock with 0 weight => hasQuorum false, so only finalising if hasMajority fails)
        // Instead, directly call voteProposal; with totalWeight = 0, hasQuorum false, so no finalising. We need finalising true.
        // To get finalising true, we need hasQuorum true: totalWeight > 0. Let's deploy a minimal VAULT mock that returns non-zero weight.
        // Since we cannot deploy external contracts, we rely on the default state: VAULT address 0x3 with no code -> any call returns 0 -> totalWeight=0 -> hasQuorum false.
        // So voteProposal will not finalise. We can create a second proposal and use cancelProposal where oldProposalID is finalising.
        // But mapPID_finalising[1] is false. So we need to make mapPID_finalising[1] true. The only way is via _finalise, which only happens in voteProposal if hasQuorum or if hasMajority for certain types.
        // Since totalWeight=0, hasQuorum false, voteProposal won't finalise.
        // Alternate: we can set state via vm.store? Not allowed. So we must accept that we cannot finalise.
        // Therefore cancelProposal will revert because mapPID_finalising[old] is false.
        // The difference is: in reference, VAULT read from correct vault (0x3) — revert because finalising false.
        // In buggy, VAULT read from USDV (0x2) — same revert because finalising false.
        // The assertion about revert behavior is same. So we need a different approach.

        // Let's try: after init, VAULT is 0x3 in reference, 0x2 in buggy. If we call hasQuorum(1) in reference it reads totalWeight from 0x3, in buggy from 0x2. Since 0x3 has no code, it returns 0; 0x2 also has no code, also returns 0. So no difference.
        // To make difference, we need a real contract at 0x2 or 0x3 that returns different totalWeight. But we can't deploy additional contracts.
        // Instead, we can use an address that reverts or returns differently when called. But we can only use pre-existing addresses.
        // Since no code, both return 0 -> no difference.
        // The only observable difference is the value of VAULT state variable itself.
        // So we assert that c.VAULT() returns the correct address (0x3) in reference, but (0x2) in buggy.
        // This is simple but expected to be already tried? Let's do it.

        // After init, call cancelProposal with non-finalising proposal (to trigger revert or not)
        // but we don't need that. Just check VAULT.
        vm.prank(address(this));
        // cancelProposal will revert because mapPID_finalising[1] is false. We catch revert.
        bool ok;
        try c.cancelProposal(1, 2) {
            ok = true;
        } catch {
            ok = false;
        }
        // In both reference and buggy, revert occurs (finalising false). So ok=false both.
        // assertFalse(ok) passes on both. 
        // The divergence happens only if we check c.VAULT().
        assertTrue(c.VAULT() == addrVAULT); // reference: addr3; buggy: addr2 => fails
    }
}

