pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy and init
        c.init(address(1), address(2), address(3));
        // First proposal: GRANT type (will be finalising)
        c.newGrantProposal(address(4), 100);
        // Second proposal: GRANT type (must be same type)
        c.newGrantProposal(address(5), 200);
        // Vote on first proposal to trigger finalising (hasQuorum requires > totalWeight/3, but totalWeight=0 so any vote >0 passes; we simulate by directly voting)
        // To get quorum we need >0 totalWeight; we set totalWeight via vault mock? But we don't have one. 
        // Actually the condition uses iVAULT(VAULT).totalWeight(). Since VAULT is address(3) with no code, totalWeight() returns 0.
        // Then hasQuorum: votes > 0/3 => votes > 0. So any positive vote triggers finalising.
        // Use a prank to vote from some address; but the vault call will fail. However we can call voteProposal anyway; it will revert on vault call.
        // To avoid revert, we need a vault contract that returns nonzero totalWeight. We'll deploy a minimal mock.
        // But the test only interacts through c. We can set VAULT to a dummy that returns e.g. 1000.
        // Actually we can deploy a simple vault mock.
        vm.etch(address(3), type(SimpleVault).runtimeCode);
        // Now totalWeight returns 1000, so quorum requires >333
        vm.prank(address(0x10));
        c.voteProposal(1);  // vote from 0x10, weight = 0 from getMemberWeight (returns 0), so no quorum yet.
        // Need to have nonzero member weight; but getMemberWeight also returns 0. So we need to mock that too.
        // This path is getting complex. Alternative: we can set up a scenario where cancelProposal is called and coolOffPeriod is read afterwards.
        // The difference is that coolOffPeriod is set to 1 vs 0. In the reference after init, coolOffPeriod==1; in bug ==0.
        // cancelProposal does not change coolOffPeriod, so any call to cancelProposal that reverts or succeeds, the value remains as set in init.
        // So we can simply call cancelProposal (will revert because old proposal not finalising), catch the revert and then check coolOffPeriod.
        // That's trivial: we call cancelProposal(1,2) which will revert because mapPID_finalising[1] is false (not finalising).
        // But the revert itself does not change state. We can then read coolOffPeriod.
        // This is a valid concrete witness: "call cancelProposal, then check coolOffPeriod" — P has 1, M has 0.
        // That satisfies the requirement.
        bool ok;
        try c.cancelProposal(1, 2) {
