        // First, create proposal 1 (GRANT type)
        vm.prank(address(0x1));
        c.newGrantProposal(address(0x2), 100);

        // Create proposal 2 (also GRANT type)
        vm.prank(address(0x1));
        c.newGrantProposal(address(0x3), 50);

        // Member 0x1 votes on proposal 1
        vm.prank(address(0x1));
        c.voteProposal(1);

        // Now cancelProposal(1,2) - this triggers the buggy countMemberVotes
