        bool ok;
        try c.finaliseProposal(1) { ok = true; } catch { ok = false; }

        // Reference: finaliseProposal fails (reverts) -> ok = false
        // Mutant: finaliseProposal succeeds -> ok = true
        assertTrue(ok == false);
    }
